class Program
{
    static List<int> ReadList()
    {
        var parts = Console.ReadLine().Split(' ', StringSplitOptions.RemoveEmptyEntries);
        var result = new List<int>();
        foreach (var p in parts)
        {
            result.Add(int.Parse(p));
        }
        return result;
    }

    static void Main()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            if (line.Trim().Length == 0) { continue; }
            int na = int.Parse(line);
            var a = na > 0 ? ReadList() : new List<int>();
            if (na == 0) { Console.ReadLine(); }
            int nb = int.Parse(Console.ReadLine());
            var b = nb > 0 ? ReadList() : new List<int>();
            if (nb == 0) { Console.ReadLine(); }

            var result = Solution.Interleave(a, b).ToList();
            Console.WriteLine(string.Join(" ", result));
        }
    }
}

