"""Random pairs of integer lists, deliberately of different lengths so the
"exhaust one side, drain the other" path is exercised often."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _line(values):
    return "%d\n%s" % (len(values), " ".join(map(str, values)) if values else "")


def _case(rng, index):
    na = rng.randint(0, 10)
    nb = rng.randint(0, 10)
    a = [rng.randint(-50, 50) for _ in range(na)]
    b = [rng.randint(-50, 50) for _ in range(nb)]
    return {"name": "lengths %d and %d #%d" % (na, nb, index),
            "stdin": _line(a) + "\n" + _line(b) + "\n"}
